// Back to regex parsing of the TOKO:/TOTAL:/ITEMS:/TANGGAL: text format
// (proven more accurate at reading item names than asking Gemini to reply with JSON directly).
const raw = $input.first().json.content.parts[0].text;

if (raw.includes('ERROR:')) {
  return [{ json: { ok: false, reason: raw.replace(/ERROR:\s*/, '').trim() } }];
}

const tokoMatch = raw.match(/TOKO:\s*(.+)/);
const totalMatch = raw.match(/TOTAL:\s*(.+)/);
const itemsMatch = raw.match(/ITEMS:\s*(.+)/);
const tanggalMatch = raw.match(/TANGGAL:\s*(.+)/);

const toko = tokoMatch ? tokoMatch[1].trim() : '';
// Total cleaned of any leftover 'Rp' or thousands separators the model might slip in
const total = totalMatch ? totalMatch[1].replace(/[^0-9]/g, '').trim() : '';
const items = itemsMatch ? itemsMatch[1].trim() : '';
let tanggal = tanggalMatch ? tanggalMatch[1].trim() : '';

// Safety net: required fields (toko & total) empty means parsing failed entirely,
// even if the model didn't explicitly say ERROR.
if (!toko || !total) {
  return [{ json: { ok: false, reason: 'Failed to parse the AI response format (toko/total empty).' } }];
}

// Second safety net: date is still required, even though the prompt already asks the AI to fill it in itself.
if (!tanggal) {
  tanggal = $now.format('yyyy-MM-dd');
}
if (!items) items = '-';

return [{ json: { ok: true, toko, total, items, tanggal } }];

