const statusCode = $json.statusCode;
const name = $('Site List').item.json.name;
const url = $('Site List').item.json.url;
const redisKey = $('Site List').item.json.redisKey;
const isUp = statusCode >= 200 && statusCode < 400;
const status = isUp ? 'up' : 'down';
const reason = isUp ? '' : ('HTTP ' + statusCode);
return { json: { name, url, redisKey, status, reason } };

const name = $('Site List').item.json.name;
const url = $('Site List').item.json.url;
const redisKey = $('Site List').item.json.redisKey;
const errorMessage = $json.error ? String($json.error) : 'Connection failed (timeout or DNS error)';
return { json: { name, url, redisKey, status: 'down', reason: errorMessage } };

const name = $('Combine Results').item.json.name;
const url = $('Combine Results').item.json.url;
const redisKey = $('Combine Results').item.json.redisKey;
const status = $('Combine Results').item.json.status;
const reason = $('Combine Results').item.json.reason;
const lastStatus = $json.lastStatus;

const isFirstCheck = lastStatus === undefined || lastStatus === null || lastStatus === '';
const changed = !isFirstCheck && lastStatus !== status;

let shouldAlert = false;
let message = '';

if (changed) {
  shouldAlert = true;
  const timeLabel = $now.toFormat('dd MMM yyyy HH:mm') + ' WIB';
  if (status === 'down') {
    message = '*DOWN* ' + name + '\n' + url + '\nReason: ' + reason + '\nTime: ' + timeLabel;
  } else {
    message = '*RECOVERED* ' + name + '\n' + url + '\nBack up at: ' + timeLabel;
  }
}

return { json: { name, url, redisKey, status, reason, shouldAlert, message } };

